python -c "
from pptx import Presentation
prs = Presentation('docs/Tech_Drawdown_Executive_Showcase.pptx')
for i, slide in enumerate(prs.slides, 1):
    texts = []
    for shape in slide.shapes:
        if shape.has_text_frame:
            t = shape.text_frame.text.strip()
            if t: texts.append(t)
    # First non-empty text block as the slide title indicator
    title = texts[0][:80] if texts else '(empty)'
    print(f'  Slide {i:2d}: {title}')
"

