# - CSS cursor:pointer (HTML/JS property, not the IDE)
# - node_modules, .git, .bob/tmp, logs, scripts/tmp

$files = Get-ChildItem -Recurse -File -Include "*.md","*.js","*.py","*.ps1","*.ts","*.json","*.html","*.txt" |
  Where-Object {
    $_.FullName -notmatch '\\node_modules\\' -and
    $_.FullName -notmatch '\\.git\\' -and
    $_.FullName -notmatch '\\logs\\' -and
    $_.FullName -notmatch '\\scripts\\tmp\\' -and
    $_.FullName -notmatch '\\.pytest_cache\\' -and
    $_.FullName -notmatch '\\tech_drawdown.egg-info\\' -and
    $_.Name -ne 'mcp-connectors-plan.md'
  }

$hits = @()
foreach ($f in $files) {
  $content = Get-Content $f.FullName -Raw -ErrorAction SilentlyContinue
  # Match "Cursor" as the IDE (capital C, not css cursor:)
  # Exclude CSS property patterns: cursor:pointer, cursor:default, cursor:help, cursor:not-allowed
  $matches = [regex]::Matches($content, '(?i)\bCursor\b') | Where-Object {
    $ctx = $content.Substring([Math]::Max(0,$_.Index-20), [Math]::Min(60, $content.Length-[Math]::Max(0,$_.Index-20)))
    $ctx -notmatch 'cursor:(pointer|default|help|not-allowed|move|text|wait|crosshair|grab|col-resize|row-resize|ew-resize|ns-resize|nwse-resize|nesw-resize|zoom)'
  }
  if ($matches.Count -gt 0) {
    $hits += "$($f.FullName -replace [regex]::Escape((Get-Location).Path+'\\'),'') : $($matches.Count) match(es)"
  }
}

if ($hits) { $hits } else { "CLEAN — no Cursor-IDE references found" }

